"""Generate an honest asset inventory; absent products remain unavailable."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];PUB=ROOT/'public';DATA=PUB/'data'
def main():
    datasets=[
      dict(id='imagery',sourceName='Viking VIS Global Color Mosaic',agency='NASA / JPL / USGS',mission='Viking 1 and 2',instrument='VIS',productName='Mars_Viking_MDIM21_ClrMosaic_global_232m',asset='/textures/mars-globe.webp',sourceUrl='https://trek.nasa.gov/tiles/Mars/EQ/Mars_Viking_MDIM21_ClrMosaic_global_232m/1.0.0/WMTSCapabilities.xml',resolution='2048 × 1024 overview, 0.17578125°/pixel; source mosaic 232 m/pixel',units='rendered RGB imagery',category='observed',processingMethod='32 level-2 WMTS tiles stitched in row/column order; WebP quality 90; no synthetic fill.',limitations=['Color composite, not calibrated reflectance.','Overview is too coarse to identify local obstacles.']),
      dict(id='mola',sourceName='MGS MOLA MEGDR',agency='NASA / GSFC / PDS',mission='Mars Global Surveyor',instrument='MOLA',productName='MEGT90N000CB.IMG v2.0',asset='/data/mola/elevation.i16',sourceUrl='https://pds-geosciences.wustl.edu/missions/mgs/megdr.html',downloadUrl='https://pds-geosciences.wustl.edu/mgs/mgs-m-mola-5-megdr-l3-v1/mgsl_300x/meg004/megt90n000cb.img',resolution='0.25° (4 pixels/degree), approximately 14.8 km north–south',units='m above GMM3 mgm1025 areoid (degree/order 50)',category='observed',observationPeriod='1997-09-15 to 2001-06-30',processingMethod='MSB signed int16 converted losslessly to little-endian; no resampling.',limitations=['Source product includes interpolation where no shots fall in a cell.','Frontend interpolation and slope are derived; not individual MOLA shots.','Not suitable for local walkability assessment.']),
      dict(id='jezero',sourceName='MRO CTX controlled Jezero mosaic',agency='NASA / JPL / USGS',mission='Mars Reconnaissance Orbiter',instrument='CTX',productName='JEZ_ctx_B_soc_008_orthoMosaic_6m_Eqc_latTs0_lon0',asset='/textures/jezero-ctx.webp',sourceUrl='https://trek.nasa.gov/tiles/Mars/EQ/JEZ_ctx_B_soc_008_orthoMosaic_6m_Eqc_latTs0_lon0/1.0.0/WMTSCapabilities.xml',resolution='approximately 10 m/pixel overview from 6 m/pixel source',units='rendered optical intensity',category='observed',processingMethod='Thirty level-12 WMTS tiles stitched with unchanged bounds.',limitations=['Optical imagery alone does not establish astronaut traversability.','Local high-resolution DEM not installed.']),
      dict(id='thermal',sourceName='MGS TES Global Thermal Inertia',agency='NASA / JPL / ASU',mission='Mars Global Surveyor',instrument='TES',productName='TES_Thermal_Inertia; Putzig et al. 2005',asset='/textures/tes-thermal-inertia.webp',sourceUrl='https://trek.nasa.gov/tiles/Mars/EQ/TES_Thermal_Inertia/1.0.0/WMTSCapabilities.xml',resolution='1024 × 512 display overview (0.3515625°/pixel); original product 20 ppd (~3 km)',units='rendered thermal-inertia context; scalar values not imported',category='derived',processingMethod='Eight level-1 NASA rendered tiles stitched losslessly, preserving transparency. Product thermal inertia is itself inferred from TES observations.',limitations=['Not a temperature map or weather forecast.','Display colors are not decoded to physical values.','Overview only; not useful for local route decisions within Jezero.','No site-specific thermal hazard or heating demand inferred.']),
      dict(id='waypoints',sourceName='NASA JPL Perseverance rover localization',agency='NASA / JPL-Caltech',mission='Mars 2020',instrument='rover localization',productName='M20_waypoints.json snapshot; selected sols 13, 180, 420',asset='/data/science-pois.json',sourceUrl='https://mars.nasa.gov/mmgis-maps/M20/Layers/json/M20_waypoints.json',resolution='Waypoint coordinates; uncertainty not supplied',units='planetocentric degrees east/north',category='observed',processingMethod='Selected exact source waypoint coordinates; no geology assigned beyond verified rover stops.',limitations=['Not live rover positions.','Rover traverse is not a certified astronaut route.','Linked panorama availability depends on NASA server; retrieval returned HTTP 403.']),
      dict(id='ice',sourceName='SWIM4MIM',agency='NASA-supported PSI project',sourceUrl='https://swim.psi.edu/SWIM4MIMProducts.php',units='ice consistency',category='derived',limitations=['Download origin returned HTTP 523; no local georeferenced ice raster.','Extractability is not established.']),
      dict(id='temperature',sourceName='NASA planetary atmospheric archives',agency='NASA',sourceUrl='https://pds-atmospheres.nmsu.edu/',units='K',category='observed',limitations=['No validated temperature observations imported.']),
      dict(id='radiation',sourceName='Curiosity RAD',agency='NASA',sourceUrl='https://science.nasa.gov/mission/msl-curiosity/science/instruments/rad/',units='mSv',category='observed',limitations=['No local radiation dataset or dose model installed.','RAD observations at Gale must not be mapped globally.'])
    ]
    for d in datasets:
        p=PUB/d.get('asset','_missing').lstrip('/')
        d['status']='installed' if p.is_file() else 'unavailable';d['installed']=p.is_file();d['downloadDate']='2026-11-15' if p.is_file() else None
        d['licenseOrUsageTerms']='Credit original agency and instrument teams; NASA media usage guidelines apply; no NASA endorsement.'
        if p.is_file():d.update(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
    (DATA/'manifest.json').write_text(json.dumps({'schemaVersion':1,'generatedDate':'2026-11-15','coordinateConvention':'Planetocentric latitude; east-positive longitude. Display imagery -180..180; raw MOLA 0..360.','datasets':datasets},indent=2))
    print([(d['id'],d['status']) for d in datasets])
if __name__=='__main__':main()
